// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;

    function setUp() public { c = new PENNY_BY_PENNY(); }

    function testFuzz_property(address logAddr, address actor) public {
        vm.assume(logAddr != address(0));
        vm.assume(actor != address(0));
        bool ok1;
        try c.SetLogFile(logAddr) {
            ok1 = true;
        } catch {
            ok1 = false;
        }
        assertTrue(ok1);

        bool ok2;
        vm.prank(actor);
        try c.SetLogFile(logAddr) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        assertTrue(ok2);
    }
}
